/*
 * The OpenAPI 3.1 document of the REST service, generated by a pure function from REST_ROUTES and the
 * schemas present() gives (presentedInput, presentedOutput), so the routes, the docs and the checks
 * cannot drift apart. The view's JSON Schema (pivotkit-core's view-2.json) is bundled into
 * components, so a client needs nothing from elsewhere. The committed copy (docs/openapi.json) is the
 * document of a server with static tokens; a running server serves its own at /openapi.json (its
 * address and its sign-in).
 */

import { createRequire } from "node:module";
import { OPERATIONS } from "pivotkit-report/operations";
import { RENDER_FORMATS } from "pivotkit-report";
import { REST_BASE } from "../config.js";
import { VERSION } from "../context.js";
import { presentedInput, presentedOutput } from "../present.js";
import { PROBLEM_CODES } from "./problem.js";
import { multipartInputSchema } from "./multipart.js";
import { REST_ROUTES } from "./routes.js";
import { NAMED_VIEW_OPERATIONS } from "../views.js";
import { RECORDS_INPUT, RECORDS_OUTPUT } from "../records.js";
import { DEFAULT_NAME, DOCS_SITE, docsLink, withDocs } from "../branding.js";

const require = createRequire(import.meta.url);

/** The statuses each kind of route can answer with besides 200, and why. */
const PROBLEMS = Object.freeze({
    400: "The input is not valid (INVALID_INPUT).",
    401: "No token, or one the service does not accept (INVALID_TOKEN).",
    403: "Not allowed: a scope missing, files by path, a host or origin refused, or (rows) no person, no right or a field below show.",
    404: "No such source or route.",
    409: "The server cannot do this: no output directory, no link page, not schedulable.",
    413: "A limit: the body, the file, the data sent, the result or (rows) the rows or cells are too large.",
    415: "The body is not JSON (or multipart/form-data with data, where allowed), or the file's format is not read.",
    422: "The file cannot be read, or (file route) the view has errors.",
    429: "Too many requests: wait as Retry-After says.",
    503: "Busy or not ready: try again as Retry-After says.",
    504: "The report took longer than the server allows."
});

/** "describe_source" as "DescribeSource". */
const pascal = (name) => name.replace(/(^|_)([a-z])/g, (_m, _s, c) => c.toUpperCase());

/**
 * The view schema of pivotkit-core, as components: its $defs beside it, every $ref pointed there,
 * its descriptions' links under the documentation's base (branding.js withDocs).
 * @param {string | null} docs
 */
function viewComponents(docs) {
    const schema = structuredClone(require("pivotkit-core/schema/view-2.json"));
    const defs = schema.$defs ?? {};
    delete schema.$schema;
    delete schema.$id;
    delete schema.$defs;
    const rewrite = (node) => {
        if (Array.isArray(node)) {
            node.forEach(rewrite);
        } else if (node && typeof node === "object") {
            for (const [key, value] of Object.entries(node)) {
                if (key === "$ref" && typeof value === "string" && value.startsWith("#/$defs/")) {
                    node.$ref = `#/components/schemas/View_${value.slice("#/$defs/".length)}`;
                } else if (key === "description" && typeof value === "string") {
                    node.description = withDocs(value, docs);
                } else {
                    rewrite(value);
                }
            }
        }
        return node;
    };
    const out = { View: rewrite(schema) };
    for (const [name, def] of Object.entries(defs)) {
        out[`View_${name}`] = rewrite(def);
    }
    return out;
}

/** A view in an input: a view, a view file, or either as JSON text. */
const VIEW_INPUT = {
    description: "The view: a JSON object with rows, cols, values, filters, derived, sort, display; or a view file; or either as JSON text.",
    anyOf: [{ $ref: "#/components/schemas/View" }, { type: "object", description: "A view file (format pivotkit-view)." }, { type: "string", description: "A view or a view file as JSON text." }]
};

/** A view in an input that takes a named view's name too (views.js NAMED_VIEW_OPERATIONS). */
const NAMED_VIEW_INPUT = {
    description: `${VIEW_INPUT.description} Or the name of a view the operator published for the source (GET /sources lists them).`,
    anyOf: [...VIEW_INPUT.anyOf.slice(0, 2), { type: "string", description: "A view or a view file as JSON text, or a named view's name." }]
};

/** The rows route's name for withViewRef: it takes a view by name, as the operations in NAMED_VIEW_OPERATIONS do. */
const RECORDS_ROUTE = "records";

/** An input schema with the view referenced: by name too for the operations and the rows route that take one. */
function withViewRef(schema, name) {
    const out = structuredClone(schema);
    if (out.properties?.view) {
        out.properties.view = NAMED_VIEW_OPERATIONS.has(name) || name === RECORDS_ROUTE ? NAMED_VIEW_INPUT : VIEW_INPUT;
    }
    return out;
}

/** An operation's input schema with the view referenced. */
const inputSchema = (name, offers, fileRoute = false) => withViewRef(presentedInput(name, { files: false, offers, fileRoute }), name);

/** The multipart body of an operation that takes a source, where data may be sent: the file and the input. */
const multipartBody = (name, offers, fileRoute = false) => ({
    schema: {
        type: "object",
        required: ["data"],
        properties: {
            data: { type: "string", contentMediaType: "application/octet-stream", description: "The file: csv, tsv, json or xlsx (by the file name's extension, else the part's content type)." },
            input: { ...withViewRef(multipartInputSchema(name, offers, fileRoute), name), description: 'The operation\'s input as JSON: source may be left out (it is "inline:"); data holds only name, asOf, sheet and sha256.' }
        }
    },
    encoding: { input: { contentType: "application/json" } }
});

/**
 * @typedef {object} OpenApiOptions
 * @property {import("../config.js").AuthOptions} [auth]  the sign-in the document describes (default: static tokens)
 * @property {string} [publicUrl]  the server's origin as clients reach it (only its origin is used)
 * @property {any} [issuer]  OAuth: the issuer's metadata (its endpoints)
 * @property {string} [resource]  OAuth: the REST resource
 * @property {string[]} [requiredScopes]  OAuth: the scopes every call needs
 * @property {import("../sources/input.js").SurfaceOffers} [offers]  the extra inputs the service offers (context.offers.rest; none by default)
 * @property {{ name: string, docs: string | null }} [branding]  the name in the title and the documentation's base (branding.js; default pivotkit's)
 */

/**
 * The OpenAPI 3.1 document.
 * @param {OpenApiOptions} [options]
 */
export function openApiDocument(options = {}) {
    const name = options.branding?.name ?? DEFAULT_NAME;
    const docs = options.branding ? options.branding.docs : DOCS_SITE;
    const auth = options.auth ?? { mode: "token" };
    const mode = auth.mode ?? "none";
    const required = options.requiredScopes ?? auth.requiredScopes ?? [];
    /** @type {Record<string, any>} */
    const securitySchemes = {};
    if (mode === "token") {
        securitySchemes.bearer = { type: "http", scheme: "bearer", description: "A token the operator gives you, static or signed: Authorization: Bearer <token>." };
    } else if (mode === "oauth") {
        const issuer = options.issuer;
        const scopes = Object.fromEntries([...new Set([...required, ...Object.values(auth.toolScopes ?? {}).flat(), ...(auth.scopesSupported ?? [])])].map((s) => [s, `the scope ${s}`]));
        securitySchemes.oauth = issuer?.authorization_endpoint && issuer?.token_endpoint
            ? { type: "oauth2", description: `An access token of ${issuer.issuer} for the resource ${options.resource ?? REST_BASE}.`, flows: { authorizationCode: { authorizationUrl: issuer.authorization_endpoint, tokenUrl: issuer.token_endpoint, scopes } } }
            : { type: "openIdConnect", openIdConnectUrl: `${String(auth.issuer ?? "").replace(/\/$/, "")}/.well-known/openid-configuration`, description: `An access token for the resource ${options.resource ?? REST_BASE}.` };
    }
    const schemeName = Object.keys(securitySchemes)[0];
    const security = (route) => (schemeName ? [{ [schemeName]: mode === "oauth" ? [...required, ...(auth.toolScopes?.[route.operation] ?? [])] : [] }] : []);

    /** @type {Record<string, any>} */
    const schemas = {
        Problem: {
            type: "object",
            description: "An error (RFC 9457 problem details).",
            required: ["type", "title", "status", "code", "detail"],
            properties: {
                type: { type: "string", format: "uri", description: "The address that names the error's code." },
                title: { type: "string" },
                status: { type: "integer" },
                code: { type: "string", description: `A stable code; new ones may come. Today: ${PROBLEM_CODES.join(", ")}.` },
                detail: { type: "string", description: "What went wrong and what to do; never file content." },
                findings: { type: "array", items: { type: "object" }, description: "The view's findings (422 of the file route)." },
                requestId: { type: "string", description: "The request's id: give it to the operator, who finds the request's log lines by it." },
                retryable: { type: "boolean", description: "For an error of a source (SOURCE_UNAVAILABLE, a print template the server cannot read too; NOT_ALLOWED, INVALID_INPUT or DATA_NOT_AVAILABLE from a source), of an upload (UPLOAD_FAILED) and for BUSY (a large body, or a parameter's pattern not checked in time): whether the same request may work when tried again (Retry-After says when, where known)." }
            }
        },
        ...viewComponents(docs)
    };
    for (const name of Object.keys(OPERATIONS)) {
        schemas[`${pascal(name)}Input`] = inputSchema(name, options.offers);
        schemas[`${pascal(name)}Output`] = presentedOutput(name);
    }
    // the file route sends the file and saves none: its input has no `save`
    for (const route of REST_ROUTES.filter((r) => r.answer === "file")) {
        schemas[`${pascal(route.id)}Input`] = inputSchema(route.operation, options.offers, true);
    }
    /** @type {Record<string, any>} */
    const responses = {};
    for (const [status, description] of Object.entries(PROBLEMS)) {
        responses[`Problem${status}`] = { description, content: { "application/problem+json": { schema: { $ref: "#/components/schemas/Problem" } } } };
    }

    // the rows route (records.js): no operation of the table, its own input and output
    schemas.ReadRecordsInput = withViewRef(RECORDS_INPUT, RECORDS_ROUTE);
    schemas.ReadRecordsOutput = structuredClone(RECORDS_OUTPUT);
    /** @type {Record<string, any>} */
    const paths = {};
    for (const route of REST_ROUTES.filter((r) => r.answer === "records")) {
        paths[`${REST_BASE}${route.path}`] = {
            post: {
                operationId: route.id,
                summary: route.summary,
                description: route.description,
                tags: ["sources"],
                ...(schemeName ? { security: security(route) } : {}),
                requestBody: { required: true, content: { "application/json": { schema: { $ref: "#/components/schemas/ReadRecordsInput" }, example: route.example.input } } },
                responses: {
                    200: { description: "The rows, columnar. The answer is written in pieces (no Content-Length).", content: { "application/json": { schema: { $ref: "#/components/schemas/ReadRecordsOutput" }, example: route.example.output } } },
                    ...Object.fromEntries([400, 401, 403, 404, 413, 415, 422, 429, 503, 504].map((status) => [status, { $ref: `#/components/responses/Problem${status}` }]))
                }
            }
        };
    }
    for (const route of REST_ROUTES.filter((r) => r.answer !== "records")) {
        const op = OPERATIONS[route.operation];
        const errors = route.method === "GET" ? (route.path.includes("{") ? [400, 401, 403, 404, 422, 429, 503, 504] : [401, 403, 429, 503]) : [400, 401, 403, 404, 409, 413, 415, 422, 429, 503, 504];
        const okContent =
            route.answer === "file"
                ? Object.fromEntries(Object.values(RENDER_FORMATS).map((f) => [f.mediaType.split(";")[0], {}]))
                : { "application/json": { schema: { $ref: `#/components/schemas/${pascal(route.operation)}Output` }, example: route.example.output } };
        paths[`${REST_BASE}${route.path}`] ??= {};
        paths[`${REST_BASE}${route.path}`][route.method.toLowerCase()] = {
            operationId: route.id,
            summary: route.summary,
            description: route.description,
            tags: [route.path.split("/")[1]],
            ...(schemeName ? { security: security(route) } : {}),
            ...(auth.toolScopes?.[route.operation]?.length ? { "x-pivotkit-scopes": auth.toolScopes[route.operation] } : {}),
            ...(route.path.includes("{id}") ? { parameters: [{ name: "id", in: "path", required: true, description: "A source id from GET /sources.", schema: { type: "string", minLength: 1, maxLength: 1024 } }] } : {}),
            ...(route.method === "POST"
                ? {
                      requestBody: {
                          required: true,
                          content: {
                              "application/json": { schema: { $ref: `#/components/schemas/${pascal(route.answer === "file" ? route.id : route.operation)}Input` }, example: route.example.input },
                              // data as a file, for callers whose profile has data: true
                              ...(options.offers?.data && /** @type {any} */ (op.input).properties?.source ? { "multipart/form-data": multipartBody(route.operation, options.offers, route.answer === "file") } : {})
                          }
                      }
                  }
                : {}),
            responses: {
                200: route.answer === "file" ? { description: `The file (${Object.keys(RENDER_FORMATS).join(", ")}), as an attachment.`, headers: { "Content-Disposition": { schema: { type: "string" } } }, content: okContent } : { description: op.title, content: okContent },
                ...Object.fromEntries(errors.map((s) => [s, { $ref: `#/components/responses/Problem${s}` }]))
            }
        };
    }

    return {
        openapi: "3.1.0",
        info: {
            title: `${name} REST`,
            version: VERSION,
            summary: "Describe data sources, validate and render pivot views, make links and draft schedules.",
            description: `The operations of ${name === DEFAULT_NAME ? "pivotkit's MCP server" : `${name}'s MCP tools`} over HTTP for programs. Errors are RFC 9457 problem details. The routes are RPC-style (POST /views/validate); /api/v1 changes only with a breaking change.${docs === null ? "" : ` Docs: ${docsLink(docs, "reference/rest/")}`}`,
            license: { name: "MIT", identifier: "MIT" }
        },
        // the paths carry /api/v1: the server is the origin
        servers: [{ url: options.publicUrl ? new URL(options.publicUrl).origin : "/" }],
        tags: [
            { name: "sources", description: "The data sources a caller may use." },
            { name: "views", description: "Views: the guide, validation, description, rendering and links." },
            { name: "schedules", description: "Drafts of scheduled reports for a person to approve." }
        ],
        paths,
        components: { schemas, responses, ...(schemeName ? { securitySchemes } : {}) }
    };
}
